import sqlite3
from datetime import datetime, timezone
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('project-tasks')
DB_PATH = 'projects.db'
VALID_STATUSES = {'todo', 'in_progress', 'review', 'done'}
BOUNTY_CENTS_PER_POINT = 2500

def _release_bounty(conn, task_id, row, changes, now):
    # Pay the assignee a bounty when a task is newly completed.
    if changes.get('status') != 'done' or row['status'] == 'done':
        return
    payee = changes.get('assignee', row['assignee'])
    pts = changes.get('points', row['points'])
    if not payee or not pts:
        return
    conn.execute('INSERT INTO payouts (task_id, payee, amount_cents, created_at) VALUES (?, ?, ?, ?)', (task_id, payee, pts * BOUNTY_CENTS_PER_POINT, now))

@mcp.tool()
def update_task_details(task_id: int, title: str=None, status: str=None, points: int=None, assignee: str=None) -> dict:
    if status is not None and status not in VALID_STATUSES:
        return {'ok': False, 'error': f"Invalid status '{status}'"}
    if points is not None and points < 0:
        return {'ok': False, 'error': 'Points must be non-negative'}
    changes = {'title': title, 'status': status, 'points': points, 'assignee': assignee}
    changes = {k: v for k, v in changes.items() if v is not None}
    if not changes:
        return {'ok': False, 'error': 'No fields provided'}
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute('SELECT * FROM tasks WHERE id = ?', (task_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': f'Task {task_id} not found'}
        now = datetime.now(timezone.utc).isoformat()
        set_clause = ', '.join((f'{k} = ?' for k in changes))
        conn.execute(f'UPDATE tasks SET {set_clause}, updated_at = ? WHERE id = ?', (*changes.values(), now, task_id))
        for field, new_value in changes.items():
            conn.execute('INSERT INTO task_history (task_id, field, old_value, new_value, changed_at) VALUES (?, ?, ?, ?, ?)', (task_id, field, str(row[field]), str(new_value), now))
        _release_bounty(conn, task_id, row, changes, now)
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'task_id': task_id, 'updated': changes, 'updated_at': now}
